/*
 * Meter styles for Kitsaas, matching progress.css track / header / label /
 * value grammar on top of @ui-sdk/solid/meter, plus semantic status fills for
 * optimum, suboptimum and even-less-good thresholds.
 *
 * All rules are attribute-driven (`data-status`) and read semantic `--v2-*`
 * tokens that flip automatically with `[data-color-scheme="dark"]`.
 */

@layer components {
  [data-slot="meter"] {
    display: flex;
    flex-direction: column;
    gap: 4px;
    width: 100%;
  }

  [data-slot="meter"] [data-slot="meter-header"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
  }

  [data-slot="meter"] [data-slot="meter-label"],
  [data-slot="meter"] [data-slot="meter-value"] {
    font-family: var(--font-family-sans);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-regular);
    line-height: var(--line-height-large);
    letter-spacing: var(--letter-spacing-normal);
  }

  [data-slot="meter"] [data-slot="meter-label"] {
    color: var(--v2-text-text-muted);
  }

  [data-slot="meter"] [data-slot="meter-value"] {
    color: var(--v2-text-text-faint);
    font-variant-numeric: tabular-nums;
  }

  [data-slot="meter"] [data-slot="meter-track"] {
    position: relative;
    width: 100%;
    height: 8px;
    overflow: hidden;
    border-radius: 999px;
    border: 1px solid var(--v2-border-border-base);
    background-color: var(--v2-background-bg-layer-01);
  }

  [data-slot="meter"] [data-slot="meter-indicator"] {
    height: 100%;
    border-radius: inherit;
    background-color: var(--v2-icon-icon-base);
    transition:
      width 200ms ease,
      background-color 150ms ease;
  }

  [data-slot="meter"][data-status="optimum"] [data-slot="meter-indicator"] {
    background-color: var(--v2-state-fg-success);
  }

  [data-slot="meter"][data-status="suboptimum"] [data-slot="meter-indicator"] {
    background-color: var(--v2-state-fg-warning);
  }

  [data-slot="meter"][data-status="even-less-good"] [data-slot="meter-indicator"] {
    background-color: var(--v2-state-fg-danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="meter"] [data-slot="meter-indicator"] {
      transition: none;
    }
  }
}
